function compare(a, b):
    for (ea,ca),(eb,cb) in zip(a.terms, b.terms):
        if ea != eb: return sign(ea - eb)
        if ca != cb: return sign(ca - cb)
    return sign(len(a.terms) - len(b.terms))

function add(a, b):
    if b = 0: return a; if a = 0: return b
    lead = exponent of b.terms[0]
    kept = [t in a.terms with exponent > lead]
    merged = copy(b.terms)
    if a has a term with exponent = lead:
        add its coefficient into merged[0]
    return kept ++ merged

function mul(a, b):
    if a = 0 or b = 0: return 0
    (le, lc) = a.terms[0]; res = 0
    for (eb, cb) in b.terms:
        if eb = 0: res = add(res, [(le, lc*cb)] ++ a.terms[1:])
        else:      res = add(res, [(le+eb, cb)])
    return res

