function mortal_forces(value, beta):
    return compare(beta, value) <= 0

function round_of_death(value):
    return value          # least round not forced

function survives_all_below(value, rounds):
    return all mortal_forces(value, b) for b in rounds

function refine_value(value, omega):
    return mul(omega, value)      # value(R(G)) = w * value(G)

function refine_iterated(base, omega, k):
    v = base
    repeat k times: v = mul(omega, v)
    return v
